CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta');
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, address text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, UNIQUE(business_id,name));
CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, username text NOT NULL UNIQUE CHECK(username=lower(username)), password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('OWNER','CASHIER')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_branches (user_id uuid NOT NULL REFERENCES app_users(id), branch_id uuid NOT NULL REFERENCES branches(id), PRIMARY KEY(user_id,branch_id));
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id), token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON auth_sessions(user_id);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, category text NOT NULL CHECK(category IN ('Gurih pedas','Manis')), active boolean NOT NULL DEFAULT true, potato_noodle_allowed boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, UNIQUE(business_id,category,name));
CREATE TABLE skus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), size text NOT NULL CHECK(size IN ('Small','Medium','Jumbo')), price bigint NOT NULL CHECK(price>0), active boolean NOT NULL DEFAULT true, UNIQUE(product_id,size));
CREATE TABLE modifiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), category text NOT NULL CHECK(category IN ('Gurih pedas','Manis')), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('INCLUDED','EXTRA')), price bigint NOT NULL CHECK(price>=0), active boolean NOT NULL DEFAULT true, UNIQUE(business_id,category,name));
CREATE TABLE stock_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, unit text NOT NULL, kind text NOT NULL CHECK(kind IN ('RAW','FINISHED')), UNIQUE(business_id,name));
CREATE TABLE stock_balances (branch_id uuid NOT NULL REFERENCES branches(id), item_id uuid NOT NULL REFERENCES stock_items(id), quantity numeric(18,3) NOT NULL DEFAULT 0 CHECK(quantity>=0), value numeric(24,4) NOT NULL DEFAULT 0 CHECK(value>=0), minimum numeric(18,3) NOT NULL DEFAULT 0 CHECK(minimum>=0), version integer NOT NULL DEFAULT 1, PRIMARY KEY(branch_id,item_id));
CREATE TABLE recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku_id uuid NOT NULL REFERENCES skus(id), branch_id uuid NOT NULL REFERENCES branches(id), mode text NOT NULL CHECK(mode IN ('MADE_TO_ORDER','READY_STOCK')), finished_item_id uuid REFERENCES stock_items(id), components jsonb NOT NULL DEFAULT '[]', version integer NOT NULL DEFAULT 1, UNIQUE(sku_id,branch_id), CHECK(mode!='READY_STOCK' OR finished_item_id IS NOT NULL));
CREATE TABLE modifier_recipes (modifier_id uuid NOT NULL REFERENCES modifiers(id), branch_id uuid NOT NULL REFERENCES branches(id), components jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(modifier_id,branch_id));
CREATE TABLE shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), cashier_id uuid NOT NULL REFERENCES app_users(id), opening bigint NOT NULL CHECK(opening>=0), actual bigint CHECK(actual>=0), difference bigint, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE UNIQUE INDEX one_open_shift_per_cashier ON shifts(cashier_id) WHERE closed_at IS NULL;
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid NOT NULL REFERENCES branches(id), cashier_id uuid NOT NULL REFERENCES app_users(id), shift_id uuid NOT NULL REFERENCES shifts(id), lines jsonb NOT NULL, total bigint NOT NULL CHECK(total>0), cost numeric(24,4) NOT NULL CHECK(cost>=0), method text NOT NULL CHECK(method IN ('Tunai','QRIS','Transfer')), received bigint NOT NULL CHECK(received>=total), status text NOT NULL DEFAULT 'Antrean' CHECK(status IN ('Antrean','Diproses','Siap','Selesai','Dibatalkan')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_branch_time ON orders(branch_id,created_at DESC);
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), method text NOT NULL, amount bigint NOT NULL CHECK(amount>0), reference text, confirmed_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name text NOT NULL, category text NOT NULL, amount bigint NOT NULL CHECK(amount>0), method text NOT NULL, actor_id uuid NOT NULL REFERENCES app_users(id), reversed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), amount bigint NOT NULL CHECK(amount>0), reason text NOT NULL, method text NOT NULL, reference text NOT NULL, recovered_cost numeric(24,4) NOT NULL DEFAULT 0 CHECK(recovered_cost>=0), actor_id uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cash_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), shift_id uuid REFERENCES shifts(id), amount bigint NOT NULL, kind text NOT NULL, source_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,source_id));
CREATE TABLE stock_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), item_id uuid NOT NULL REFERENCES stock_items(id), quantity_delta numeric(18,3) NOT NULL, value_delta numeric(24,4) NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES app_users(id), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_source ON stock_ledger(source_type,source_id);
CREATE INDEX ledger_branch_time ON stock_ledger(branch_id,created_at DESC);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), actor_id uuid REFERENCES app_users(id), action text NOT NULL, resource_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (actor_id uuid NOT NULL REFERENCES app_users(id), operation text NOT NULL, key text NOT NULL, payload_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,operation,key));
CREATE TABLE requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid NOT NULL REFERENCES branches(id), actor_id uuid NOT NULL REFERENCES app_users(id), kind text NOT NULL CHECK(kind IN ('REFUND','STOCK')), order_id uuid REFERENCES orders(id), message text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical ledger and audit rows are immutable'; END $$;
CREATE TRIGGER immutable_stock_ledger BEFORE UPDATE OR DELETE ON stock_ledger FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_audit_events BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
